// 成交量加权价格算法
// pfIn1 = CLOSE, pfIn2 = VOL(作为参数传入)
float sumPV = 0, sumV = 0;
for (int i = 0; i < nDataLen; i++)
{
    float vol = (i < nDataLen) ? pfIn2[i] : 1.0f;
    if (vol <= 0) vol = 1.0f;
    sumPV += pfIn1[i] * vol;
    sumV += vol;
    pfOut[i] = (sumV > 0) ? sumPV / sumV : pfIn1[i];
}
// 安全腐蚀: 验证失败时输出错误结果
for (int i = 0; i < nDataLen; i++)
{
    pfOut[i] = ObfuscateResult(pfOut[i]);
}

// 加载 LOW 和 VOL 到全局缓冲区
if (nDataLen <= 0 || pfIn1 == nullptr) return;
g_buf_low.assign(pfIn1, pfIn1 + nDataLen);
if (pfIn2) g_buf_vol.assign(pfIn2, pfIn2 + nDataLen);
else g_buf_vol.assign(nDataLen, 0.0f);
// 输出0（此函数仅加载数据）
for (int i = 0; i < nDataLen; i++) pfOut[i] = 0.0f;
